/**
 * Whether a file is generated (regenerated by a build step, so writing into it is data loss) or
 * source. Ported from Impeccable's engine (github.com/pbakaus/impeccable, Apache-2.0; see
 * NOTICE).
 *
 * This matters before any edit: when the element the user picked lives in a file a build script
 * rewrites, writing variants or accepted changes into it is silent data loss — the next build
 * wipes them. Two signals, in order of reliability: git's own ignore check, then a generated-file
 * header marker in the first few hundred bytes, which catches projects without git.
 */
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

const HEADER_SCAN_BYTES = 300;
const HEADER_MARKERS: readonly RegExp[] = [
	/@generated\b/i,
	/\bGENERATED\s+FILE\b/,
	/\bAUTO-?GENERATED\b/i,
	/\bDO\s+NOT\s+EDIT\b/i,
];

/** True when `filePath` is gitignored. A non-repo or an error counts as "not known to be ignored". */
function isGitIgnored(absPath: string, cwd: string): boolean {
	try {
		// argv form, never a shell: this runs on every file a source walk reaches, so a hostile
		// filename embedding `$(…)` or backticks must not be interpretable.
		execFileSync("git", ["check-ignore", "--quiet", absPath], { cwd, stdio: "ignore" });
		return true; // exit 0 means ignored
	} catch {
		// Exit 1 is "not ignored"; exit 128 is "not a repo" or another error. Neither is evidence.
		return false;
	}
}

/** True when the file's head carries a generated-file marker. */
function hasGeneratedHeader(absPath: string): boolean {
	let fd: number | undefined;
	try {
		fd = fs.openSync(absPath, "r");
		const buf = Buffer.alloc(HEADER_SCAN_BYTES);
		const bytesRead = fs.readSync(fd, buf, 0, HEADER_SCAN_BYTES, 0);
		const head = buf.subarray(0, bytesRead).toString("utf-8");
		return HEADER_MARKERS.some((re) => re.test(head));
	} catch {
		return false;
	} finally {
		if (fd !== undefined) {
			try {
				fs.closeSync(fd);
			} catch {
				// Already closed.
			}
		}
	}
}

/** True when the file is generated, by git ignore or by a header marker. */
function isGeneratedFile(filePath: string, { cwd = process.cwd() }: { readonly cwd?: string } = {}): boolean {
	const absPath = path.isAbsolute(filePath) ? filePath : path.resolve(cwd, filePath);
	if (isGitIgnored(absPath, cwd)) return true;
	return hasGeneratedHeader(absPath);
}

export { HEADER_MARKERS, HEADER_SCAN_BYTES, hasGeneratedHeader, isGeneratedFile, isGitIgnored };
